9	export async function createTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
10	  const user = await requireUser();
11	  const parsed = z
12	    .object({
13	      subject: z.string().min(3).max(150),
14	      body: z.string().min(5).max(10000),
15	      priority: z.enum(["LOW", "NORMAL", "HIGH", "URGENT"]).default("NORMAL"),
16	    })
17	    .safeParse({
18	      subject: formData.get("subject"),
19	      body: formData.get("body"),
20	      priority: formData.get("priority") ?? "NORMAL",
21	    });
22	  if (!parsed.success) return { error: "Subject (3+) and message (5+) required." };
23	
24	  const ticket = await db.ticket.create({
25	    data: {
26	      subject: parsed.data.subject,
27	      priority: parsed.data.priority,
28	      userId: user.id,
29	      messages: { create: { body: parsed.data.body, authorId: user.id, isStaff: false } },
30	    },
31	  });
32	  const admins = await db.user.findMany({ where: { role: "ADMIN" } });
33	  await db.notification.createMany({
34	    data: admins.map((a) => ({
35	      userId: a.id,
36	      title: `New ticket: ${parsed.data.subject}`,
37	      href: `/admin/support/${ticket.id}`,
38	    })),
39	  });
40	  redirect(`/dashboard/support/${ticket.id}`);
41	}
42	
43	export async function replyTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
44	  const user = await requireUser();
45	  const ticketId = String(formData.get("ticketId") ?? "");
46	  const body = String(formData.get("body") ?? "").trim();
47	  if (body.length < 2 || body.length > 10000) return { error: "Message too short." };
48	
49	  const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
50	  if (!ticket) return { error: "Ticket not found." };
51	  const isStaff = user.role === "ADMIN" && ticket.userId !== user.id;
52	  if (ticket.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
53	
54	  await db.$transaction([
55	    db.ticketMessage.create({ data: { ticketId, body, authorId: user.id, isStaff } }),
56	    db.ticket.update({
57	      where: { id: ticketId },
58	      data: { status: isStaff ? "ANSWERED" : "CUSTOMER_REPLY" },
59	    }),
60	  ]);
61	
62	  if (isStaff) {
63	    await db.notification.create({
64	      data: {
65	        userId: ticket.userId,
66	        title: `Support replied: ${ticket.subject}`,
67	        href: `/dashboard/support/${ticketId}`,
68	      },
69	    });
70	  } else {
71	    const admins = await db.user.findMany({ where: { role: "ADMIN" } });
72	    await db.notification.createMany({
73	      data: admins.map((a) => ({
74	        userId: a.id,
75	        title: `Ticket reply: ${ticket.subject}`,
76	        href: `/admin/support/${ticketId}`,
77	      })),
78	    });
79	  }
80	  revalidatePath(`/dashboard/support/${ticketId}`);
81	  revalidatePath(`/admin/support/${ticketId}`);
82	  return {};
83	}
84	
85	export async function setTicketStatus(ticketId: string, status: "OPEN" | "CLOSED") {
86	  const user = await requireUser();
87	  const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
88	  if (!ticket) throw new Error("Not found");
89	  if (ticket.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
90	  await db.ticket.update({ where: { id: ticketId }, data: { status } });
91	  revalidatePath(`/dashboard/support/${ticketId}`);
92	  revalidatePath(`/admin/support/${ticketId}`);
93	}
94	
95	export async function setTicketPriority(ticketId: string, priority: "LOW" | "NORMAL" | "HIGH" | "URGENT") {
96	  await requireAdmin();
97	  await db.ticket.update({ where: { id: ticketId }, data: { priority } });
98	  revalidatePath(`/admin/support/${ticketId}`);
99	}
