"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "./db";
import { requireUser } from "./auth";
import { requireArea } from "./rbac";

const KINDS = ["BUG", "FEATURE"] as const;
const STATUSES = ["NEW", "PLANNED", "IN_PROGRESS", "DONE", "DECLINED"] as const;

export type Kind = (typeof KINDS)[number];
export type FeedbackStatus = (typeof STATUSES)[number];

/**
 * Customer-facing: file a bug report or feature request. Called directly (with
 * positional args) from the floating FeedbackWidget and the dashboard form.
 */
export async function submitFeedback(
  kind: string,
  title: string,
  body: string,
  url: string
): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();

  const parsed = z
    .object({
      kind: z.enum(KINDS),
      title: z.string().trim().min(3).max(150),
      body: z.string().trim().min(5).max(5000),
      url: z.string().trim().max(500).optional(),
    })
    .safeParse({ kind, title, body, url });

  if (!parsed.success) {
    return { error: "Please add a title (3+ chars) and a description (5+ chars)." };
  }

  await db.feedback.create({
    data: {
      userId: user.id,
      kind: parsed.data.kind,
      title: parsed.data.title,
      body: parsed.data.body,
      url: parsed.data.url && parsed.data.url.length > 0 ? parsed.data.url : null,
    },
  });

  // Ping staff so triage sees it.
  const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
  if (admins.length > 0) {
    await db.notification.createMany({
      data: admins.map((a) => ({
        userId: a.id,
        title: `New ${parsed.data.kind === "BUG" ? "bug report" : "feature request"}: ${parsed.data.title}`,
        href: `/admin/feedback`,
      })),
    });
  }

  revalidatePath("/dashboard/feedback");
  revalidatePath("/admin/feedback");
  return { ok: true };
}

/** Admin triage: change status and/or set an internal note. */
export async function adminUpdateFeedback(
  id: string,
  status: string,
  adminNote: string
): Promise<{ error?: string; ok?: boolean }> {
  await requireArea("support");

  const parsed = z
    .object({
      id: z.string().min(1),
      status: z.enum(STATUSES),
      adminNote: z.string().trim().max(2000),
    })
    .safeParse({ id, status, adminNote });

  if (!parsed.success) return { error: "Invalid status or note." };

  const existing = await db.feedback.findUnique({ where: { id: parsed.data.id } });
  if (!existing) return { error: "Feedback not found." };

  await db.feedback.update({
    where: { id: parsed.data.id },
    data: {
      status: parsed.data.status,
      adminNote: parsed.data.adminNote.length > 0 ? parsed.data.adminNote : null,
    },
  });

  // Let the reporter know their item moved forward.
  if (existing.userId && parsed.data.status !== existing.status) {
    await db.notification.create({
      data: {
        userId: existing.userId,
        title: `Your ${existing.kind === "BUG" ? "bug report" : "feature request"} is now ${parsed.data.status.replace(/_/g, " ").toLowerCase()}`,
        href: `/dashboard/feedback`,
      },
    });
  }

  revalidatePath("/dashboard/feedback");
  revalidatePath("/admin/feedback");
  return { ok: true };
}

/** Admin listing with optional kind/status filter. */
export async function adminListFeedback(filter?: { kind?: string; status?: string }) {
  await requireArea("support");
  const where: { kind?: string; status?: string } = {};
  if (filter?.kind && (KINDS as readonly string[]).includes(filter.kind)) where.kind = filter.kind;
  if (filter?.status && (STATUSES as readonly string[]).includes(filter.status)) where.status = filter.status;
  return db.feedback.findMany({
    where,
    include: { user: { select: { email: true, name: true } } },
    orderBy: { createdAt: "desc" },
  });
}

"use client";

import { useState, useTransition } from "react";
import { submitFeedback } from "@/lib/actions-feedback";

type Kind = "BUG" | "FEATURE";

/**
 * Shared bug/feature form. Captures the current path as `url` on submit and
 * calls the `submitFeedback` server action. Shows a thank-you state when done.
 * Reused by the floating widget and the dashboard feedback page.
 */
export function FeedbackForm({
  onDone,
  compact,
}: {
  onDone?: () => void;
  compact?: boolean;
}) {
  const [kind, setKind] = useState<Kind>("BUG");
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [done, setDone] = useState(false);
  const [pending, start] = useTransition();

  function reset() {
    setKind("BUG");
    setTitle("");
    setBody("");
    setError(null);
    setDone(false);
  }

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    const url = typeof window !== "undefined" ? window.location.pathname : "";
    start(async () => {
      const res = await submitFeedback(kind, title, body, url);
      if (res?.error) {
        setError(res.error);
        return;
      }
      setDone(true);
    });
  }

  if (done) {
    return (
      <div className="flex flex-col items-center justify-center gap-3 py-8 text-center">
        <div className="rounded-2xl border border-emerald-500/30 bg-emerald-500/10 p-3">
          <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="#34d399" strokeWidth="2">
            <path d="M20 6 9 17l-5-5" />
          </svg>
        </div>
        <h3 className="text-base font-semibold">Thanks for the feedback!</h3>
        <p className="max-w-xs text-sm text-slate-400">
          We&apos;ve logged your {kind === "BUG" ? "bug report" : "feature request"} and the team will take a look.
        </p>
        <div className="flex gap-2">
          <button className="btn-secondary" onClick={reset}>
            Send another
          </button>
          {onDone && (
            <button className="btn-primary" onClick={onDone}>
              Done
            </button>
          )}
        </div>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      {error && (
        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
          {error}
        </div>
      )}

      <div className="grid grid-cols-2 gap-2">
        <button
          type="button"
          onClick={() => setKind("BUG")}
          className={
            kind === "BUG"
              ? "btn-primary justify-center"
              : "btn-secondary justify-center"
          }
        >
          🐞 Report a bug
        </button>
        <button
          type="button"
          onClick={() => setKind("FEATURE")}
          className={
            kind === "FEATURE"
              ? "btn-primary justify-center"
              : "btn-secondary justify-center"
          }
        >
          ✨ Request a feature
        </button>
      </div>

      <div>
        <label className="label">Title</label>
        <input
          className="input"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder={kind === "BUG" ? "What went wrong?" : "What would you like to see?"}
          minLength={3}
          maxLength={150}
          required
        />
      </div>

      <div>
        <label className="label">Description</label>
        <textarea
          className={`input resize-y ${compact ? "min-h-24" : "min-h-32"}`}
          value={body}
          onChange={(e) => setBody(e.target.value)}
          placeholder={
            kind === "BUG"
              ? "Steps to reproduce, what you expected, and what actually happened."
              : "Describe the feature and how it would help you."
          }
          minLength={5}
          maxLength={5000}
          required
        />
      </div>

      <div className="flex items-center justify-end gap-3">
        {onDone && (
          <button type="button" className="btn-ghost" onClick={onDone} disabled={pending}>
            Cancel
          </button>
        )}
        <button className="btn-primary px-6" disabled={pending}>
          {pending ? "Sending…" : "Submit"}
        </button>
      </div>
    </form>
  );
}

