"use client";

import { useState, useTransition } from "react";
import { adminUpdateFeedback } from "@/lib/actions-feedback";

const STATUSES = ["NEW", "PLANNED", "IN_PROGRESS", "DONE", "DECLINED"] as const;

/**
 * Per-row triage control: a status dropdown + an internal admin note that saves
 * together. Both persist via `adminUpdateFeedback`.
 */
export function FeedbackRowControls({
  id,
  status,
  adminNote,
}: {
  id: string;
  status: string;
  adminNote: string | null;
}) {
  const [nextStatus, setNextStatus] = useState(status);
  const [note, setNote] = useState(adminNote ?? "");
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<{ error?: string; ok?: boolean }>({});

  const dirty = nextStatus !== status || note !== (adminNote ?? "");

  function save() {
    setMsg({});
    start(async () => {
      const res = await adminUpdateFeedback(id, nextStatus, note);
      setMsg(res ?? {});
    });
  }

  return (
    <div className="flex min-w-[240px] flex-col gap-2">
      <select
        className="input w-full py-1.5 text-xs"
        value={nextStatus}
        onChange={(e) => setNextStatus(e.target.value)}
        disabled={pending}
      >
        {STATUSES.map((s) => (
          <option key={s} value={s}>
            {s.replace(/_/g, " ").toLowerCase()}
          </option>
        ))}
      </select>
      <textarea
        className="input min-h-16 w-full resize-y py-1.5 text-xs"
        value={note}
        onChange={(e) => setNote(e.target.value)}
        placeholder="Internal note (shown to reporter)…"
        maxLength={2000}
        disabled={pending}
      />
      <div className="flex items-center gap-2">
        <button
          className="btn-primary py-1 text-xs"
          disabled={pending || !dirty}
          onClick={save}
        >
          {pending ? "Saving…" : "Save"}
        </button>
        {msg.ok && !dirty && <span className="text-xs text-emerald-400">Saved</span>}
        {msg.error && <span className="text-xs text-red-400">{msg.error}</span>}
      </div>
    </div>
  );
}

import Link from "next/link";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, EmptyState, timeAgo } from "@/components/ui/primitives";
import { FeedbackRowControls } from "@/components/admin/FeedbackControls";

export const dynamic = "force-dynamic";

const KINDS = ["BUG", "FEATURE"] as const;
const STATUSES = ["NEW", "PLANNED", "IN_PROGRESS", "DONE", "DECLINED"] as const;

const statusTone: Record<string, "slate" | "brand" | "amber" | "green" | "red"> = {
  NEW: "slate",
  PLANNED: "brand",
  IN_PROGRESS: "amber",
  DONE: "green",
  DECLINED: "red",
};

function filterHref(kind: string | undefined, status: string | undefined): string {
  const p = new URLSearchParams();
  if (kind) p.set("kind", kind);
  if (status) p.set("status", status);
  const q = p.toString();
  return q ? `/admin/feedback?${q}` : "/admin/feedback";
}

function Pill({
  active,
  href,
  children,
}: {
  active: boolean;
  href: string;
  children: React.ReactNode;
}) {
  return (
    <Link
      href={href}
      className={
        active
          ? "rounded-full border border-brand-500/50 bg-brand-500/15 px-3 py-1 text-xs font-medium text-brand-200"
          : "rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-xs font-medium text-slate-400 hover:text-slate-200"
      }
    >
      {children}
    </Link>
  );
}

export default async function AdminFeedbackPage({
  searchParams,
}: {
  searchParams: Promise<{ kind?: string; status?: string }>;
}) {
  await requireArea("support");
  const sp = await searchParams;

  const kind = (KINDS as readonly string[]).includes(sp.kind ?? "") ? sp.kind : undefined;
  const status = (STATUSES as readonly string[]).includes(sp.status ?? "") ? sp.status : undefined;

  const where: { kind?: string; status?: string } = {};
  if (kind) where.kind = kind;
  if (status) where.status = status;

  const items = await db.feedback.findMany({
    where,
    include: { user: { select: { email: true, name: true } } },
    orderBy: { createdAt: "desc" },
  });

  const openCount = await db.feedback.count({ where: { status: { in: ["NEW", "PLANNED", "IN_PROGRESS"] } } });

  return (
    <div className="space-y-6">
      <PageHeader
        title="Feedback"
        sub={`Bug reports and feature requests from customers. ${openCount} open.`}
      />

      <div className="card space-y-3">
        <div className="flex flex-wrap items-center gap-2">
          <span className="mr-1 text-xs font-medium text-slate-500">Type</span>
          <Pill active={!kind} href={filterHref(undefined, status)}>
            All
          </Pill>
          {KINDS.map((k) => (
            <Pill key={k} active={kind === k} href={filterHref(k, status)}>
              {k === "BUG" ? "Bugs" : "Features"}
            </Pill>
          ))}
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <span className="mr-1 text-xs font-medium text-slate-500">Status</span>
          <Pill active={!status} href={filterHref(kind, undefined)}>
            All
          </Pill>
          {STATUSES.map((s) => (
            <Pill key={s} active={status === s} href={filterHref(kind, s)}>
              {s.replace(/_/g, " ").toLowerCase()}
            </Pill>
          ))}
        </div>
      </div>

      {items.length === 0 ? (
        <EmptyState
          title="No feedback matches"
          sub="Nothing here for the current filter. Try widening it."
        />
      ) : (
        <div className="card overflow-x-auto p-0">
          <table className="table-shell min-w-[900px]">
            <thead>
              <tr>
                <th>Type</th>
                <th>Details</th>
                <th>From</th>
                <th>Status</th>
                <th>Triage</th>
                <th className="text-right">Submitted</th>
              </tr>
            </thead>
            <tbody>
              {items.map((f) => (
                <tr key={f.id}>
                  <td>
                    <Badge tone={f.kind === "BUG" ? "red" : "brand"}>
                      {f.kind === "BUG" ? "bug" : "feature"}
                    </Badge>
                  </td>
                  <td className="max-w-sm">
                    <div className="font-semibold text-slate-100">{f.title}</div>
                    <div className="mt-0.5 whitespace-pre-wrap text-xs text-slate-400">{f.body}</div>
                    {f.url && (
                      <div className="mt-1 font-mono text-[11px] text-slate-500">on {f.url}</div>
                    )}
                  </td>
                  <td className="text-xs text-slate-400">
                    {f.user ? (
                      <>
                        <div className="text-slate-300">{f.user.name}</div>
                        <div>{f.user.email}</div>
                      </>
                    ) : (
                      <span className="text-slate-500">deleted user</span>
                    )}
                  </td>
                  <td>
                    <Badge tone={statusTone[f.status] ?? "slate"}>
                      {f.status.replace(/_/g, " ").toLowerCase()}
                    </Badge>
                  </td>
                  <td>
                    <FeedbackRowControls id={f.id} status={f.status} adminNote={f.adminNote} />
                  </td>
                  <td className="text-right text-xs text-slate-400">{timeAgo(f.createdAt)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

